import {
    asAdmin,
    asGuest,
    asUser,
    mustBeLoggedIn,
    mustBeLoggedInAsAdmin,
} from './utils/auth';
import { expect, test } from './utils/base';

test.describe('Users Admin Page with Auth Mocking', () => {
    test('denies access to guest users', async ({ page }) => {
